parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "type": {
      "type": "string",
      "enum": [
        "Bug",
        "Task",
        "none"
      ],
      "description": "Bug for a defect, Task for an improvement idea, none when no ticket is needed"
    },
    "product": {
      "type": "string",
      "enum": [
        "NovaCRM",
        "NovaPay",
        "NovaPlanning",
        "NovaDesk",
        "Other"
      ],
      "description": "Product concerned, Other if none of the four"
    },
    "summary": {
      "type": "string",
      "description": "One-line title of the problem or idea, without the product name, 80 characters at most"
    },
    "reporter": {
      "type": "string",
      "description": "Who reported it: name and role from the signature, e.g. \"Jane Doe, Head of Sales\"; the sender's name if the email is not signed"
    },
    "description": {
      "type": "string",
      "description": "2 to 4 sentences for the dev team: what happens (or what is asked), where in the product, who is affected; rephrased, never copied"
    },
    "steps": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Bug: steps to reproduce from the email, one short action each, at most 8; [\"Not stated in the email\"] if the email gives none or for a Task"
    },
    "expected": {
      "type": "string",
      "description": "Bug: the expected behaviour; Task: the need and the wished result; one or two sentences"
    },
    "actual": {
      "type": "string",
      "description": "Bug: what actually happens; Task: how it works today; one or two sentences, \"Not stated in the email\" if absent"
    },
    "impact": {
      "type": "string",
      "description": "Who is affected, how badly, and the workaround if there is one; one or two sentences"
    },
    "investigation_leads": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "2 or 3 short hypotheses for developers to check first (which component or rule may cause it); hypotheses, not facts"
    },
    "acceptance_criteria": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "2 to 4 short, testable conditions that prove the ticket is done"
    },
    "priority": {
      "type": "string",
      "enum": [
        "Highest",
        "High",
        "Medium",
        "Low",
        "Lowest"
      ],
      "description": "Jira priority"
    },
    "label": {
      "type": "string",
      "enum": [
        "back",
        "front"
      ],
      "description": "back for the server and data, front for the interface"
    },
    "confidence": {
      "type": "string",
      "enum": [
        "high",
        "low"
      ],
      "description": "high when the email clearly reports a defect or asks for an improvement in a named product; low only when you cannot tell"
    },
    "reason": {
      "type": "string",
      "description": "One sentence that explains your choice, above all anything that makes you hesitate"
    }
  },
  "required": [
    "type",
    "product",
    "summary",
    "reporter",
    "description",
    "steps",
    "expected",
    "actual",
    "impact",
    "investigation_leads",
    "acceptance_criteria",
    "priority",
    "label",
    "confidence",
    "reason"
  ],
  "additionalProperties": false
}
